mapper.select:
select clinic_item.org_id as orgId, item.id as itemId, item.name as itemName, atype.name as typeName, item.duration, item.remarks, item.inservice from appoint_item item LEFT JOIN clinic_appoint_item citem ON item.id = clinic_item.appoint_item_id LEFT JOIN appoint_type atype ON atype.id = item.appoint_type_id where citem.org_id = #{form.orgId}
and citem.id = #{form.appointId}
and citem.name = #{form.name}

select item.id, cai.appoint_item_id as appointItemId, item.name as itemName, item.duration, item.inservice, item.remarks from appoint_item item LEFT JOIN clinic_appoint_item cai ON cai.appoint_item_id = item.id where cai.org_id=#{form.orgId}
and cai.appoint_item_id=#{form.appointItemId}
and itm.name like CONCAT(CONCAT('%', #{form.name}), '%')
